macro_rules! deflatePending {
    () => {
        # [doc = " Returns the number of bytes and bits of output that have been generated, but not yet provided in the available output."] # [doc = ""] # [doc = " The bytes not provided would be due to the available output space having being consumed."] # [doc = " The number of bits of output not provided are between `0` and `7`, where they await more bits to join them in order to fill out a full byte."] # [doc = " If pending or bits are `NULL`, then those values are not set."] # [doc = ""] # [doc = " # Returns"] # [doc = ""] # [doc = " - [`Z_OK`] if success"] # [doc = " - [`Z_STREAM_ERROR`] if the source stream state was inconsistent"] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " The caller must guarantee that"] # [doc = ""] # [doc = " * Either"] # [doc = "     - `strm` is `NULL`"] # [doc = "     - `strm` satisfies the requirements of `&mut *strm` and was initialized with [`deflateInit_`] or similar"] # [doc = " * Either"] # [doc = "     - `pending` is `NULL`"] # [doc = "     - `pending` satisfies the requirements of [`core::ptr::write::<c_int>`]"] # [doc = " * Either"] # [doc = "     - `bits` is `NULL`"] # [doc = "     - `bits` satisfies the requirements of [`core::ptr::write::<c_int>`]"] # [cfg_attr (feature = "export-symbols" , export_name = prefix ! (deflatePending))] pub unsafe extern "C-unwind" fn deflatePending (strm : z_streamp , pending : * mut c_uint , bits : * mut c_int ,) -> c_int { let Some (stream) = (unsafe { DeflateStream :: from_stream_mut (strm) }) else { return ReturnCode :: StreamError as _ ; } ; let (current_pending , current_bits) = stream . pending () ; if let Some (pending) = unsafe { pending . as_mut () } { * pending = current_pending as c_uint ; } if let Some (bits) = unsafe { bits . as_mut () } { * bits = current_bits as c_int ; } ReturnCode :: Ok as _ }
    };
}

deflatePending!()